syntax:
union MyUnion {
    int intValue;   // Member 1: 4 bytes (typically)
    float floatValue;  // Member 2: 4 bytes, shares memory with intValue
    // Implementation note: Only one member is active after assignment. Accessing a non-active member (e.g., reading floatValue after writing intValue) triggers undefined behavior due to potential type aliasing violations. The compiler aligns the union based on the strictest alignment requirement (e.g., 4 bytes for both on x86).

code_example:
#include <iostream>

union MyUnion {
    int intValue;     // Active when assigned
    float floatValue; // Shares the same memory
};

int main() {
    MyUnion u;  // Union object created, no member active initially
    u.intValue = 10;  // Makes intValue the active member
    float f = u.floatValue;  // Lvalue-to-rvalue conversion on non-active member: undefined behavior
    std::cout << f << std::endl;  // May print garbage or cause runtime error
    return 0;
}
